import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.vLhlLNVn.js";const m=JSON.parse('{"title":"Was brauche ich, bevor ich den Adapter installiere?","description":"","frontmatter":{"order":1,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/01.erste-schritte/01.voraussetzungen.md"},"headers":[],"relativePath":"de/adapter/esphome/erste-schritte/voraussetzungen.md","filePath":"de/adapter/esphome/erste-schritte/voraussetzungen.md","lastUpdated":1795388431000}'),s={name:"de/adapter/esphome/erste-schritte/voraussetzungen.md"};function n(d,e,h,o,u,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="was-brauche-ich-bevor-ich-den-adapter-installiere" tabindex="-1">Was brauche ich, bevor ich den Adapter installiere? <a class="header-anchor" href="#was-brauche-ich-bevor-ich-den-adapter-installiere" aria-label="Permalink to &quot;Was brauche ich, bevor ich den Adapter installiere?&quot;">​</a></h1><p><a id="have-install-python-pip-myself"></a></p><h2 id="muss-ich-python-oder-pip-selbst-installieren" tabindex="-1">Muss ich Python oder pip selbst installieren? <a class="header-anchor" href="#muss-ich-python-oder-pip-selbst-installieren" aria-label="Permalink to &quot;Muss ich Python oder pip selbst installieren?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="systems-hardware-adapter-run"></a></p><h2 id="auf-welchen-systemen-und-mit-welcher-hardware-lauft-der-adapter" tabindex="-1">Auf welchen Systemen und mit welcher Hardware läuft der Adapter? <a class="header-anchor" href="#auf-welchen-systemen-und-mit-welcher-hardware-lauft-der-adapter" aria-label="Permalink to &quot;Auf welchen Systemen und mit welcher Hardware läuft der Adapter?&quot;">​</a></h2><p><strong>Kurz:</strong> Der Adapter selbst läuft auf jedem System mit ioBroker und Node.js 22 oder neuer. Das integrierte ESPHome-Dashboard wird nur auf <strong>64-Bit-Linux und macOS</strong> unterstützt, nicht auf 32-Bit-Systemen und nicht unter Windows.</p><p>Für die Geräte braucht der Adapter kein Python. Er spricht direkt über die Native API mit ihnen. Python braucht nur das integrierte Dashboard: Beim Start legt der Adapter dafür eine eigene Umgebung mit Python 3.13 an und installiert ESPHome hinein. Das klappt nur auf Systemen, für die es passende Python- und ESPHome-Pakete gibt.</p><table tabindex="0"><thead><tr><th>Was</th><th>Voraussetzung</th></tr></thead><tbody><tr><td>Adapter mit Geräten</td><td>ioBroker, Node.js 22 oder neuer, jedes Betriebssystem</td></tr><tr><td>Integriertes Dashboard</td><td>zusätzlich 64-Bit-Linux oder macOS und beim Start Internetzugang</td></tr><tr><td>Integriertes Dashboard auf 32-Bit (z. B. Raspberry Pi OS 32 Bit) oder Windows</td><td>nicht unterstützt, nutze ein externes Dashboard</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Auch ein Raspberry Pi mit 64-Bit-Kernel kann ein 32-Bit-System sein, wenn das Betriebssystem in 32 Bit installiert ist. Bei Nutzern lief das Dashboard erst nach einer Neuinstallation mit einem 64-Bit-Betriebssystem.</p></div><h3 id="welche-hardware-brauche-ich" tabindex="-1">Welche Hardware brauche ich? <a class="header-anchor" href="#welche-hardware-brauche-ich" aria-label="Permalink to &quot;Welche Hardware brauche ich?&quot;">​</a></h3><p>Für den Betrieb mit Geräten reicht jede Hardware, auf der ioBroker läuft. Feste Mindestwerte für das Dashboard gibt es nicht. Das Dashboard kompiliert aber Firmware, und das braucht viel Rechenleistung und Arbeitsspeicher. Auf schwacher Hardware wie einem Raspberry Pi 3 kann das den ganzen Rechner ausbremsen, ein Raspberry Pi 4 lief bei Nutzern stabil.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Ist dein ioBroker-Rechner schwach, ein 32-Bit-System oder ein Windows-Rechner, lass das integrierte Dashboard aus und betreibe ein externes ESPHome-Dashboard auf einem anderen Rechner. Der Adapter braucht für die Geräte kein Dashboard.</p></div><p><strong>Siehe auch:</strong> <a href="./../anleitungen/dashboard-nutzen#use-external-esphome-dashboard-instead">Wie nutze ich ein externes ESPHome-Dashboard statt des integrierten?</a></p><p><a id="need-home-assistant-mqtt-use"></a></p><h2 id="brauche-ich-home-assistant-oder-mqtt-um-esphome-gerate-in-iobroker-zu-nutzen" tabindex="-1">Brauche ich Home Assistant oder MQTT, um ESPHome-Geräte in ioBroker zu nutzen? <a class="header-anchor" href="#brauche-ich-home-assistant-oder-mqtt-um-esphome-gerate-in-iobroker-zu-nutzen" aria-label="Permalink to &quot;Brauche ich Home Assistant oder MQTT, um ESPHome-Geräte in ioBroker zu nutzen?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',17)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
